WITH leaf_tasks AS (
  SELECT work_item_id, est_hours
  FROM work_items
  WHERE engagement_id = (SELECT engagement_id FROM engagements WHERE code = :project_code)
    AND NOT EXISTS (
      SELECT 1 FROM work_items AS children WHERE children.parent_item_id = work_items.work_item_id
    )
)
SELECT CAST(COALESCE(SUM(est_hours), 0) AS REAL) AS total_leaf_est_hours
FROM leaf_tasks;
